n=19
g=[[0]*n for _ in range(n)]
pluses=[(3,6,8),(4,13,4),(12,14,1),(14,3,2)]
empty=(10,8)
# outlines
outl=set()
for r,c,_ in pluses:
    outl|={(r-1,c),(r+1,c),(r,c-1),(r,c+1)}
outl|={(empty[0]-1,empty[1]),(empty[0]+1,empty[1]),(empty[0],empty[1]-1),(empty[0],empty[1]+1)}
blockers=set(outl)|{empty}
for r,c,col in pluses:
    g[r][c]=col
    for dr,dc in ((0,1),(0,-1),(1,0),(-1,0)):
        rr,cc=r+dr,c+dc
        while 0<=rr<n and 0<=cc<n:
            if (rr,cc) in outl and (rr,cc) not in {(r-1,c),(r+1,c),(r,c-1),(r,c+1)}:
                break  # other plus outline blocks
            if (rr,cc)==empty:
                break
            if (rr,cc) in outl:
                rr,cc=rr+dr,cc+dc; continue  # own outline: skip
            g[rr][cc]=col
            rr,cc=rr+dr,cc+dc
# vertical overrides horizontal: repaint vertical last
for r,c,col in pluses:
    for dr in (1,-1):
        rr,cc=r+dr,c
        while 0<=rr<n:
            if (rr,cc) in outl and (rr,cc) not in {(r-1,c),(r+1,c)}:
                break
            if (rr,cc)==empty: break
            if (rr,cc) in outl:
                rr+=dr; continue
            g[rr][cc]=col
            rr+=dr
for row in g: print(row)
